"""Build a review gallery from real 13B browser captures; never synthesize a render."""
import html
import json
import pathlib

out=pathlib.Path('docs/mission-13-evidence/materials')
c=json.loads(pathlib.Path('public/materials/authentic/catalog.json').read_text())
s=json.loads((out/'summary.json').read_text())
esc=lambda x:html.escape(str(x),quote=True)
decisions={
 'stone-rubble':'Piste prioritaire pour 13C : irrégularité plus naturelle que les assises du témoin, contraste contenu. La répétition de la source de 2 m demeure visible à grande échelle.',
 'stone-coursed':'Réserve : autre appareillage, plus régulier. Échelle 2 m interprétée et lithologie locale inconnue ; ne pas le présenter comme calcaire observé.',
 'plaster-fine':'Témoin procédural déjà satisfaisant. Le grain photographique apporte un écart discret ; ne le substituer que si un essai en rue prouve son intérêt.',
 'plaster-worn':'Réserve pour variations d’enduit : les lacunes deviennent très discrètes en hybride. Le PBR montre mieux leur structure mais ses taches sont plus marquées.',
 'roof-flat':'Piste à juger : éléments plus petits et moins bombés que le témoin. La lecture des rangs est très fine en hybride ; conserver le témoin si elle scintille ou paraît trop uniforme dans la rue.',
 'gravel':'Piste conditionnelle pour les surfaces déjà documentées en gravier. Le PBR est très granuleux ; l’hybride reste plus discret et doit encore justifier son coût en promenade.',
 'earth-dry':'Terre générique de bibliothèque, sans nouvelle attribution géographique. Gain proche modéré ; conserver l’herbe et la litière existantes.',
 'bank-soil':'Réserve de contact humide, pas une berge universelle. Ni substrat, ni profondeur, ni débit réels déduits.',
 'rock-layered':'Alternative structurée ; les strates sont lisibles mais l’échelle 2,5 m reste artistique. Ne pas remplacer automatiquement la roche existante.',
 'rock-existing':'Même source que Mission 12, maintenant étudiée à la largeur fournisseur 2,7 m. Le témoin conserve son échelle antérieure 27 m. L’écart révèle autant le calibrage que le shader.'}

def triptych(file,alt):
 return f'<div class="legend"><span>Photographique · PBR</span><span>Mission 12 · témoin</span><span>Hybride · palette M12</span></div><a href="{file}"><img loading="lazy" src="{file}" alt="{esc(alt)}"></a>'

cards=[]
for e in c['entries']:
 author=', '.join(e['author'].keys()) if isinstance(e['author'],dict) else e['author']
 cards.append(f'<section id="{e["id"]}"><p class="eyebrow">{esc(e["family"])} · {esc(e["metres"])} mètres par tuile</p><h2>{esc(e["label"])}</h2>'+triptych(e['id']+'-close-afternoon-clear.jpg',e['label']+' : trois approches, même géométrie et caméra')+f'<p>{esc(decisions[e["id"]])}</p><p class="small">Source : <a href="{esc(e["source"])}">{esc(author)}</a> · CC0 · {esc(e["scaleStatus"])}. Relief {e["reliefM"]*1000:g} mm : amplitude artistique de normales, aucun déplacement géométrique.</p></section>')
wide=''.join('<h3>'+esc(next(e['label'] for e in c['entries'] if e['id']==i))+'</h3>'+triptych(i+'-wide-afternoon-clear.jpg','Grande surface de répétition : '+i) for i in ['stone-rubble','plaster-worn','roof-flat','gravel'])
lighting=''.join('<h3>'+esc(moment+' · '+weather)+'</h3>'+triptych('stone-rubble-close-'+moment+'-'+weather+'.jpg','Pierre sous '+moment+' / '+weather) for moment,weather in s['lightingCases'])
rows=[]
for profile in ['eco','balanced','quality']:
 for ident in ['stone-rubble','roof-flat','gravel']:
  values=[next(m for m in s['metrics'] if m['profile']==profile and m['id']==ident and m['approach']==a) for a in ['photographic','procedural','hybrid']]
  rows.append('<tr><td>'+esc(profile)+'</td><td>'+esc(ident)+'</td>'+''.join(f'<td>{v["medianMs"]:.1f} / {v["p95Ms"]:.1f}</td>' for v in values)+'</tr>')
atlasrows=''.join(f'<tr><td>{f["file"]}</td><td>{f["bytes"]:,}</td><td>{f["gpuBytesWithMipmapsEstimate"]/1048576:.2f} Mio</td><td>{esc(f["colorSpace"])}</td></tr>' for f in c['files'])
document='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>Endless Earth · Bibliothèque 13B</title><style>*{box-sizing:border-box}body{margin:0;background:#f0ede2;color:#293e32;font:16px/1.6 system-ui}header,main,footer{max-width:1440px;margin:auto;padding:32px}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:clamp(2.4rem,5vw,4.4rem);line-height:1.15;max-width:1000px}h2{font-size:2rem}p{max-width:1100px}section{border-top:1px solid #c5c9b6;padding:32px 0}a{color:#36634d;overflow-wrap:anywhere}img{display:block;width:100%;height:auto}.legend{display:grid;grid-template-columns:repeat(3,1fr);background:#dce3d3;text-align:center;font-size:.85rem;padding:10px;gap:10px}.eyebrow,.small{font-size:.85rem;color:#596a5c}.notice{padding:20px;background:#dfe6d6;border-left:4px solid #6a806b}nav{display:flex;gap:18px;flex-wrap:wrap}table{border-collapse:collapse;width:100%;font-size:.9rem}td,th{padding:9px;text-align:left;border-bottom:1px solid #c5c9b6}.table{overflow:auto}code{font-size:.8rem;overflow-wrap:anywhere}@media(max-width:700px){header,main,footer{padding:16px}.legend{font-size:.65rem;padding:6px;gap:4px}section{padding:20px 0}}</style><header><p class="eyebrow">ENDLESS EARTH · Jalon 13B</p><h1>Dix matières à éprouver dans le paysage</h1><p>Une bibliothèque CC0 partagée, préparée hors ligne. Pierre, enduits, tuile, gravier, terres et deux roches sont comparés au vrai témoin Mission 12, sous son ciel et sa lumière.</p><p class="notice"><strong>Bibliothèque et scène de matériaux uniquement.</strong> Le village, sa géographie et son rendu n’ont pas été modifiés. Les images ci-dessous proviennent du véritable navigateur WebGL ; chaque trio conserve les mêmes positions, la même caméra et le même instant. Le PBR utilise couleur, hauteur fournisseur et rugosité ; l’hybride garde une réponse Lambert et une seule texture de données. L’intégration géographique appartient à 13C, après votre accord.</p><nav><a href="#collection">Dix matières</a><a href="#repetition">Grandes surfaces</a><a href="#lumiere">Lumière et météo</a><a href="#cout">Coût mesuré</a><a href="../../../fixtures/materials.html?perf=1&moment=afternoon&weather=clear&date=2026-06-21T12:00:00Z">Atelier interactif</a><a href="../../mission-13.md">Rapport principal</a></nav></header><main><div id="collection">'''+''.join(cards)+'''</div><section id="repetition"><h2>Voir aussi les répétitions</h2><p>Surfaces synthétiques de 24 m : aucune rotation aléatoire des rangs de tuiles ou des joints. Décalage stable par identité, faible variation à plusieurs mètres et détails filtrés ; les motifs d’une seule prise restent répétables. Ces vues ne sont pas des rues réellement parcourues.</p>'''+wide+'''<h3>Lointain · 80 m</h3>'''+triptych('stone-rubble-far-afternoon-clear.jpg','Pierre à 80 mètres')+'''</section><section id="lumiere"><h2>La même pierre du matin à la nuit</h2><p>Les dix matériaux ont passé les sept situations ci-dessous. Le relief vient des cartes du fournisseur, avec amplitude artistique ; les normales ne sont pas déduites d’une seule photo et les sommets restent fixes. Les couleurs résiduelles et les ombres photographiques du PBR ne sont pas une mesure d’albédo local.</p>'''+lighting+'''</section><section id="cout"><h2>Le coût et les limites</h2><p>405 rendus synchronisés avec lecture complète des pixels, Chromium/SwiftShader, 800 × 600. Trois passages alternés, 15 échantillons par combinaison ; médiane / P95 en millisecondes. Ces mesures décrivent cette scène logicielle simple, pas le coût dans le village, un GPU physique ou Android.</p><div class="table"><table><thead><tr><th>Profil</th><th>Matière</th><th>PBR</th><th>M12</th><th>Hybride</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p>Les shaders, le nombre de lectures et l’éclairage diffèrent entre les approches : c’est précisément le compromis étudié. Un gain dans l’atelier n’est pas extrapolé au jeu. Le gravier hybride peut coûter davantage que son témoin ; conserver les meilleures solutions procédurales reste possible.</p><div class="table"><table><thead><tr><th>Atlas partagé</th><th>Fichier compressé, octets</th><th>GPU estimé, mipmaps inclus</th><th>Interprétation</th></tr></thead><tbody>'''+atlasrows+'''</tbody></table></div><p>L’hybride occupe environ 5,06 Mio estimés pour dix emplacements utiles dans un atlas à douze cases ; le PBR environ 7,59 Mio sur deux atlas. Ce sont des comptes de texels, pas une mesure d’allocation GPU. La scène de comparaison garde les trois approches en mémoire ; elle n’est pas un budget de promenade.</p><p>Trois rechargements restent à 7 géométries et 10 textures, avec 7 programmes après le premier rechargement chaud. Une nouvelle image corrompue conserve la dernière bibliothèque valide. Aucun appel à un fournisseur pendant les inspections. Deux préparations donnent les mêmes fichiers et empreintes.</p><p><a href="summary.json">Mesures lisibles</a> · <a href="measurements.json.gz">Trace complète compressée</a> · <a href="preservation.json">Préservation et reproduction</a> · <a href="README.md">Procédure locale</a> · <a href="/endless-earth/materials/authentic/catalog.json">Catalogue des matériaux</a></p><p class="notice">Les sources et cartes sont CC0 ; les auteurs et licences restent dans le catalogue. <strong>Correction d’échelle :</strong> Rock Face 03 fait 2,7 m selon le fournisseur ; les 27 m de Mission 12 sont conservés uniquement dans le témoin historique, sans correction du jeu ici. Les échelles de Bricks099 et Rock023 restent explicitement artistiques.</p><p><strong>À valider :</strong> priorité à la pierre et aux enduits, dessin très fin de la tuile, retenue du contraste, variantes à garder en réserve et coût du gravier. <strong>Arrêt après 13B : attendre votre accord explicite pour intégrer ces matières en 13C.</strong></p></section></main><footer>0 € · Aucun merge ni déploiement. Source et dérivés de bibliothèque sous CC0 ; art procédural original Endless Earth. Les échantillons n’attribuent aucune nouvelle matière à un bâtiment réel.</footer></html>'''
(out/'index.html').write_text(document)
(out/'decisions.json').write_text(json.dumps(decisions,ensure_ascii=False,indent=2)+'\n')
print('Generated 13B gallery')
